Method.Implementation:
 #dim status as %Status	 
 set status = $$$OK
 $$$TRACE("Inside OnMessage method<" _ pRequest.StringValue _ ">")

 try{		
	$$$TRACE("Connect to " _ ..ApplicationAddress)
	$$$TRACE("Connect to " _ ..TuxedoService)
	$$$TRACE(" JavaGateWay Host : " _ ..Address)
     $$$TRACE(" JavaGateWay Port : " _ ..Port)

      set gtw = ##class(%Net.Remote.Gateway).%New()
	  set sc = gtw.%Connect(..Address,..Port,,,)
	  $$$TRACE(" **SC**"_sc)		

	set ..objCdrTuxService = ##class(org.ihc.itf.cdr.drc.CdrDrcLastRunReportDate).%New(gtw,..ApplicationAddress, ..TuxedoService, ..LogDirectory _"/" _$$$JobConfigName _".log", $$$ConfigTrace($$$JobConfigName))     	
	set output = ..objCdrTuxService.GetLastReportDate(..DrcUser)
	set pResponse = ##class(IHC.ITF.Response.OpCdrGetReportDate).%New()
    $$$TRACE("Output after invocation of GetLastReportDate Java Method<" _ output _ ">")
    $$$TRACE("Last run Report Date (Response): <" _ output _ ">")

	if ($L(output) > 0){
		if ($E(output,1,6)="ERROR:"){
			if (output [ "TPESVCFAIL"){
				set pResponse.errMsg = output
				set status=##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("Op-Cdr-Dsql-GETREPORTDATE"," Error while calling the DSQL TuxedoService:  "_output)
			}
		}else{
			set pResponse.reportDate = output	    
		}
	}
}catch err{
	$$$TRACE(" Error while getting LastRun Report Date..Err Data: "_err.Data_" Err Code:"_err.Code_" Err Status: "_err.AsStatus())
	Set status = err.AsStatus()
	Set status =  ##class(IHC.ITF.ITFCOMMON.Utility).ProcessError(err.AsStatus())				
}		

 $$$TRACE("OnMessage(GetLastReportDate) status: " _ status)	

 return status

$$$TRACE(" $$$$$ Inside OnTearDown() method...")
set tSC = $$$OK

try {		
	if $IsObject(..objCdrTuxService) {
		$$$TRACE("Disconnecting from CDR Tuxedo service...")
		do ..objCdrTuxService.shutdownTuxService()			
		set ..objCdrTuxService = $$$NULLOREF
		$$$TRACE("Disconnected - CDR Tuxedo service...")
	}
} catch {
	set tSC = $$$EnsSystemError
}

$$$TRACE("OnTearDown, status: " _ tSC)
quit tSC
